  headers: {
    "content-type": "application/json",
  },
  body: {
    id: 42,
    title: "Campus Film Night",
    location: "Auditorium",
  },
};

function classifyStatus(status) {
  if (status >= 200 && status < 300) return "success";
  if (status >= 400 && status < 500) return "client error";
  if (status >= 500) return "server error";
  return "other";
}

function getContentType(headers) {
  return headers["content-type"] ?? "unknown";
}

function summarizeBody(body) {
  if (Array.isArray(body)) return `${body.length} item(s)`;
  if (body && typeof body === "object" && "title" in body) {
    return `Event: ${body.title}`;
  }
  return "No event summary";
}

function buildInspectionReport(response) {
  return [
    `${response.method} ${response.endpoint}`,
    `Status: ${response.status} (${classifyStatus(response.status)})`,
    `Content-Type: ${getContentType(response.headers)}`,
    `Body: ${summarizeBody(response.body)}`,
  ].join("\n");
}

console.log(buildInspectionReport(response));
